import React, { useContext } from 'react';
import { NavLink } from 'react-router-dom';
import {
  LayoutDashboard,
  Users,
  BookOpen,
  CheckSquare,
  Clock,
  DollarSign,
  FileBarChart2,
  Bell,
  Settings,
  BookMarked,
  User,
} from 'lucide-react';
import { AuthContext } from '../../context/AuthContext';

const Sidebar = () => {
  const { user } = useContext(AuthContext);
  const isAdmin = user?.role === 'Admin' || user?.role === 'Super Admin';

  const adminNav = [
    { label: 'Dashboard', path: '/admin/dashboard', icon: LayoutDashboard },
    { label: 'Employees', path: '/admin/employees', icon: Users },
    { label: 'Projects', path: '/admin/projects', icon: BookOpen },
    { label: 'Task Management', path: '/admin/tasks', icon: CheckSquare },
    { label: 'Attendance Log', path: '/admin/attendance', icon: Clock },
    { label: 'Payroll & Salary', path: '/admin/payroll', icon: DollarSign },
    { label: 'System Reports', path: '/admin/reports', icon: FileBarChart2 },
    { label: 'Notifications', path: '/admin/notifications', icon: Bell },
    { label: 'Settings', path: '/admin/settings', icon: Settings },
  ];

  const employeeNav = [
    { label: 'Dashboard', path: '/employee/dashboard', icon: LayoutDashboard },
    { label: 'My Tasks', path: '/employee/tasks', icon: CheckSquare },
    { label: 'My Attendance', path: '/employee/attendance', icon: Clock },
    { label: 'My Salary & Slips', path: '/employee/salary', icon: DollarSign },
    { label: 'Notifications', path: '/employee/notifications', icon: Bell },
    { label: 'My Profile', path: '/employee/profile', icon: User },
  ];

  const navItems = isAdmin ? adminNav : employeeNav;

  return (
    <aside className="sidebar">
      <div className="sidebar-logo">
        <div
          style={{
            width: '36px',
            height: '36px',
            borderRadius: '10px',
            background: 'linear-gradient(135deg, var(--primary), var(--accent))',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            color: '#ffffff',
          }}
        >
          <BookMarked size={22} />
        </div>
        <div>
          <div className="sidebar-logo-text">PUSTAK MARKET</div>
          <div style={{ fontSize: '0.7rem', color: 'var(--text-muted)', fontWeight: 600 }}>EMS Enterprise</div>
        </div>
      </div>

      <nav className="sidebar-menu">
        {navItems.map((item) => {
          const Icon = item.icon;
          return (
            <NavLink
              key={item.path}
              to={item.path}
              className={({ isActive }) => (isActive ? 'sidebar-link active' : 'sidebar-link')}
            >
              <Icon size={18} />
              <span>{item.label}</span>
            </NavLink>
          );
        })}
      </nav>

      <div className="sidebar-footer">
        <div
          style={{
            padding: '12px',
            background: 'var(--bg-input)',
            borderRadius: '10px',
            fontSize: '0.75rem',
            color: 'var(--text-secondary)',
          }}
        >
          <div style={{ fontWeight: 700, color: 'var(--primary)' }}>Book Publishing EMS</div>
          <div>v1.0.0 (Production)</div>
        </div>
      </div>
    </aside>
  );
};

export default Sidebar;
